anch:@"feature" action:@"create" error:&error]);REQUIRE(![s branch:@"feature" action:@"switch" error:&error]);error=nil;REQUIRE([s stage:@[@"中文.m"] remove:NO error:&error]);REQUIRE([s commit:@"Second" name:@"Test" email:@"test@example.com" error:&error]!=nil);REQUIRE([s branch:@"feature" action:@"switch" error:&error]);REQUIRE([[NSString stringWithContentsOfFile:[root stringByAppendingPathComponent:@"中文.m"] encoding:NSUTF8StringEncoding error:nil] containsString:@"= 1"]);REQUIRE([[s branches:&error] count]==2);REQUIRE([[s history:&error] count]==2);REQUIRE([s branch:@"main" action:@"switch" error:&error]);REQUIRE([[s history:&error] count]==3);[NSFileManager.defaultManager removeItemAtPath:[root stringByAppendingPathComponent:@"中文.m"] error:nil];REQUIRE([s stage:@[@"中文.m"] remove:NO error:&error]);REQUIRE([s commit:@"Delete" name:@"Test" email:@"test@example.com" error:&error]!=nil);REQUIRE([s branch:@"feature" action:@"delete" error:&error]);REQUIRE(![s setRemote:@"https://user:secret@github.com/example/repo" error:&error]);error=nil;REQUIRE([s setRemote:@"https://github.com/example/repo.git" error:&error]);REQUIRE([[s status:&error][@"remote"] isEqual:@"https://github.com/example/repo.git"]);NSLog(@"GitService: %lu checks passed; fixture %@",(unsigned long)checks,root);return 0;}}
